CREATE DATABASE IF NOT EXISTS computer_lab CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE computer_lab;
CREATE TABLE IF NOT EXISTS computers (pc_no INT NOT NULL PRIMARY KEY, config TEXT NOT NULL, status VARCHAR(60) NOT NULL DEFAULT 'OK', problem TEXT NULL, repair_details TEXT NULL, notes TEXT NULL, updated_at VARCHAR(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

